#![cfg(feature = "cpp")]

use code_gen::cpp::*;
use code_gen::*;

/// The first line of a generated file.
const DO_NOT_EDIT: &str = "// DO NOT EDIT: This file was generated by the ProtoPacket compiler.";

/// Gets the type of the bytes of an encoding.
fn bytes_type() -> CppType {
    CppType::from("std::vector").with_generic("std::uint8_t")
}

/// Gets the type of a view of the bytes of an encoding.
fn span_type() -> CppType {
    CppType::from("std::span").with_generic(CppType::from("std::uint8_t").to_const())
}

/// Gets the signature of the `encode` function of the `Point` struct.
fn point_encode() -> Signature {
    Signature::from("encode")
        .with_result(bytes_type())
        .with_modifier(Modifier::Const)
}

/// Gets the signature of the `decode` function of the `Point` struct.
fn point_decode() -> Signature {
    Signature::from("decode")
        .with_param(("bytes", span_type()))
        .with_result(CppType::from("std::optional").with_generic("Point"))
        .with_modifier(Modifier::Static)
}

#[test]
fn struct_header() {
    let u32_type = CppType::from("std::uint32_t");
    let mut class = Class::from("Point")
        .with_comment(" The `Point` example of `format/binary.md`.")
        .with_constant(
            ConstInit::from((("ENCODED_LEN", "std::size_t"), Literal::from("8")))
                .with_comment(" The length of the encoding, in bytes.")
                .with_access(Access::Public)
                .with_modifier(Modifier::Static),
        )
        .with_constructor(
            Constructor::from("Point")
                .with_comment(" Creates the Point with every field zero.")
                .with_access(Access::Public)
                .with_modifier(Modifier::Default),
        )
        .with_constructor(
            Constructor::from("Point")
                .with_comment(" Creates the Point.")
                .with_access(Access::Public)
                .with_modifier(Modifier::Constexpr)
                .with_modifier(Modifier::Noexcept)
                .with_param(("x", u32_type.clone()))
                .with_param(("y", u32_type.clone()))
                .with_initializer("x_", "x")
                .with_initializer("y_", "y"),
        );
    for (operator, result) in [("operator==", "bool"), ("operator<=>", "auto")] {
        class.add_signature_dec(
            SignatureDec::from(
                Signature::from(operator)
                    .with_param(("other", CppType::from("Point").to_const().to_ref()))
                    .with_result(result)
                    .with_modifier(Modifier::Const)
                    .with_modifier(Modifier::Default),
            )
            .with_access(Access::Public),
        );
    }
    class.add_signature_dec(
        SignatureDec::from(point_encode())
            .with_comment(" Encodes the struct.")
            .with_attribute("nodiscard")
            .with_access(Access::Public),
    );
    class.add_signature_dec(
        SignatureDec::from(point_decode())
            .with_comment(" Decodes the struct from the `bytes`.")
            .with_comment("")
            .with_comment(" Returns nothing if the `bytes` are not a valid encoding.")
            .with_attribute("nodiscard")
            .with_access(Access::Public),
    );
    for field in ["x", "y"] {
        class.add_function(
            Function::from(
                Signature::from(field)
                    .with_result(u32_type.clone())
                    .with_modifier(Modifier::Constexpr)
                    .with_modifier(Modifier::Const)
                    .with_modifier(Modifier::Noexcept),
            )
            .with_comment(format!(" Gets the field: `{field}`."))
            .with_attribute("nodiscard")
            .with_access(Access::Public)
            .with_semi(format!("return {field}_")),
        );
        class.add_function(
            Function::from(
                Signature::from(format!("set_{field}"))
                    .with_param((field, u32_type.clone()))
                    .with_modifier(Modifier::Constexpr)
                    .with_modifier(Modifier::Noexcept),
            )
            .with_comment(format!(" Sets the field: `{field}`."))
            .with_access(Access::Public)
            .with_semi(format!("{field}_ = {field}")),
        );
        class.add_field(
            Field::from((format!("{field}_"), u32_type.clone())).with_default_value("0"),
        );
    }
    class.add_function(
        Function::from(
            Signature::from("encode_to")
                .with_param(("out", "O"))
                .with_result("O")
                .with_modifier(Modifier::Const),
        )
        .with_comment(" Writes the encoding of the struct to the `out` iterator.")
        .with_generic(Var::from(("O", "std::output_iterator<std::uint8_t>")))
        .with_access(Access::Public)
        .with_semi("out = proto_packet::io::write_u32(x_, out)")
        .with_semi("return proto_packet::io::write_u32(y_, out)"),
    );
    let point_type = CppType::from("format::examples::Point");
    let hash = Class::from(format!("std::hash<{point_type}>"))
        .with_struct(true)
        .with_function(
            Function::from(
                Signature::from("operator()")
                    .with_param(("point", point_type.to_const().to_ref()))
                    .with_result("std::size_t")
                    .with_modifier(Modifier::Const)
                    .with_modifier(Modifier::Noexcept),
            )
            .with_access(Access::Public)
            .with_semi("return proto_packet::io::hash(point.x(), point.y())"),
        );
    let mut header = Block::default()
        .with_literal(DO_NOT_EDIT)
        .with_empty_line()
        .with_literal("#pragma once")
        .with_empty_line();
    for path in [
        "compare",
        "cstddef",
        "cstdint",
        "functional",
        "iterator",
        "optional",
        "span",
        "vector",
    ] {
        header.add_statement(Include::from(path));
    }
    let header = header
        .with_empty_line()
        .with_statement(Include::from("proto_packet/io.h").with_quoted(true))
        .with_empty_line()
        .with_statement(Namespace::from("format::examples").with_statement(class))
        .with_empty_line()
        .with_literal("template <>")
        .with_statement(hash);

    let expected = r#"// DO NOT EDIT: This file was generated by the ProtoPacket compiler.

#pragma once

#include <compare>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <iterator>
#include <optional>
#include <span>
#include <vector>

#include "proto_packet/io.h"

namespace format::examples {

/// The `Point` example of `format/binary.md`.
class Point {
public:
    /// The length of the encoding, in bytes.
    static constexpr std::size_t ENCODED_LEN = 8;

    /// Creates the Point with every field zero.
    Point() = default;

    /// Creates the Point.
    constexpr Point(std::uint32_t x, std::uint32_t y) noexcept : x_(x), y_(y) {}

    bool operator==(const Point& other) const = default;
    auto operator<=>(const Point& other) const = default;

    /// Encodes the struct.
    [[nodiscard]] std::vector<std::uint8_t> encode() const;

    /// Decodes the struct from the `bytes`.
    ///
    /// Returns nothing if the `bytes` are not a valid encoding.
    [[nodiscard]] static std::optional<Point> decode(std::span<const std::uint8_t> bytes);

    /// Gets the field: `x`.
    [[nodiscard]] constexpr std::uint32_t x() const noexcept {
        return x_;
    }

    /// Sets the field: `x`.
    constexpr void set_x(std::uint32_t x) noexcept {
        x_ = x;
    }

    /// Gets the field: `y`.
    [[nodiscard]] constexpr std::uint32_t y() const noexcept {
        return y_;
    }

    /// Sets the field: `y`.
    constexpr void set_y(std::uint32_t y) noexcept {
        y_ = y;
    }

    /// Writes the encoding of the struct to the `out` iterator.
    template <std::output_iterator<std::uint8_t> O>
    O encode_to(O out) const {
        out = proto_packet::io::write_u32(x_, out);
        return proto_packet::io::write_u32(y_, out);
    }

private:
    std::uint32_t x_ = 0;
    std::uint32_t y_ = 0;
};

} // namespace format::examples

template <>
struct std::hash<format::examples::Point> {
    std::size_t operator()(const format::examples::Point& point) const noexcept {
        return proto_packet::io::hash(point.x(), point.y());
    }
};
"#;
    assert_eq!(header.to_code(), expected);
}

#[test]
fn struct_source() {
    let encode = Function::from(point_encode().to_scoped("Point"))
        .with_semi(format!("{} out", bytes_type()))
        .with_semi("out.reserve(ENCODED_LEN)")
        .with_semi("encode_to(std::back_inserter(out))")
        .with_semi("return out");
    let mut decode = Function::from(point_decode().to_scoped("Point")).with_statement(
        IfStatement::from("bytes.size() != ENCODED_LEN")
            .with_success_statements(Block::default().with_semi("return std::nullopt")),
    );
    for (field, offset) in [("x", 0), ("y", 4)] {
        decode.add_statement(VarInit::from((
            (field, CppType::from("std::uint32_t").to_const()),
            Literal::from(format!("proto_packet::io::read_u32(bytes, {offset})")),
        )));
    }
    decode.add_semi("return Point(x, y)");
    let source = Block::default()
        .with_literal(DO_NOT_EDIT)
        .with_empty_line()
        .with_statement(Include::from("point.h").with_quoted(true))
        .with_empty_line()
        .with_statement(
            Namespace::from("format::examples")
                .with_statement(encode)
                .with_empty_line()
                .with_statement(decode),
        );

    let expected = r#"// DO NOT EDIT: This file was generated by the ProtoPacket compiler.

#include "point.h"

namespace format::examples {

std::vector<std::uint8_t> Point::encode() const {
    std::vector<std::uint8_t> out;
    out.reserve(ENCODED_LEN);
    encode_to(std::back_inserter(out));
    return out;
}

std::optional<Point> Point::decode(std::span<const std::uint8_t> bytes) {
    if (bytes.size() != ENCODED_LEN) {
        return std::nullopt;
    }
    const std::uint32_t x = proto_packet::io::read_u32(bytes, 0);
    const std::uint32_t y = proto_packet::io::read_u32(bytes, 4);
    return Point(x, y);
}

} // namespace format::examples
"#;
    assert_eq!(source.to_code(), expected);
}

#[test]
fn enum_with_unrecognized_tag_numbers() {
    let color = Enum::from("Color")
        .with_comment(" The `Color` example of `format/binary.md`.")
        .with_comment("")
        .with_comment(" A tag number the enum doesn't know is a value with no case.")
        .with_underlying_type("std::uint16_t")
        .with_case(EnumCase::from("Red").with_comment(" Red.").with_value("1"))
        .with_case(
            EnumCase::from("Green")
                .with_comment(" Green.")
                .with_value("2"),
        );
    let from_tag_number = Function::from(
        Signature::from("color_from_tag_number")
            .with_param(("tag_number", "std::uint16_t"))
            .with_result("Color")
            .with_modifier(Modifier::Constexpr)
            .with_modifier(Modifier::Noexcept),
    )
    .with_comment(" Gets the `Color` with the `tag_number`.")
    .with_attribute("nodiscard")
    .with_semi("return static_cast<Color>(tag_number)");
    let mut names = SwitchStatement::from("color");
    for case in ["Red", "Green"] {
        names.add_switch_case(
            SwitchCase::from(format!("Color::{case}"))
                .with_semi(format!("return \"{case}\""))
                .with_break(false),
        );
    }
    names.add_switch_case(
        SwitchCase::default()
            .with_semi("return std::nullopt")
            .with_break(false),
    );
    let name = Function::from(
        Signature::from("color_name")
            .with_param(("color", "Color"))
            .with_result(CppType::from("std::optional").with_generic("std::string_view"))
            .with_modifier(Modifier::Constexpr)
            .with_modifier(Modifier::Noexcept),
    )
    .with_comment(" Gets the name of the `color`, or nothing if the enum doesn't know it.")
    .with_attribute("nodiscard")
    .with_statement(names);
    let code = Block::default()
        .with_statement(color)
        .with_empty_line()
        .with_statement(from_tag_number)
        .with_empty_line()
        .with_statement(name);

    let expected = r#"/// The `Color` example of `format/binary.md`.
///
/// A tag number the enum doesn't know is a value with no case.
enum class Color : std::uint16_t {
    /// Red.
    Red = 1,

    /// Green.
    Green = 2,
};

/// Gets the `Color` with the `tag_number`.
[[nodiscard]] constexpr Color color_from_tag_number(std::uint16_t tag_number) noexcept {
    return static_cast<Color>(tag_number);
}

/// Gets the name of the `color`, or nothing if the enum doesn't know it.
[[nodiscard]] constexpr std::optional<std::string_view> color_name(Color color) noexcept {
    switch (color) {
        case Color::Red: {
            return "Red";
        }
        case Color::Green: {
            return "Green";
        }
        default: {
            return std::nullopt;
        }
    }
}
"#;
    assert_eq!(code.to_code(), expected);
}

#[test]
fn variant() {
    let cases = [("Circle", "circle", 1), ("Square", "square", 2)];
    let unrecognized = Class::from("UnrecognizedShape")
        .with_comment(" A case of a `Shape` that the variant doesn't know.")
        .with_struct(true)
        .with_field(
            Field::from(("tag_number", "std::uint16_t"))
                .with_comment(" The tag number of the case.")
                .with_access(Access::Public),
        )
        .with_field(
            Field::from(("bytes", bytes_type()))
                .with_comment(" The encoding of the value of the case.")
                .with_access(Access::Public),
        );
    let mut value = CppType::from("std::variant").with_generic("UnrecognizedShape");
    let mut tag_numbers = SwitchStatement::from("value_.index()");
    for (index, (case, _, tag_number)) in cases.into_iter().enumerate() {
        value = value.with_generic(case);
        tag_numbers.add_switch_case(
            SwitchCase::from((index + 1).to_string())
                .with_semi(format!("return {tag_number}"))
                .with_break(false),
        );
    }
    tag_numbers.add_switch_case(
        SwitchCase::default()
            .with_semi("return std::get<UnrecognizedShape>(value_).tag_number")
            .with_break(false),
    );
    let mut shape = Class::from("Shape")
        .with_comment(" The `Shape` example of `format/binary.md`.")
        .with_type_dec(
            TypeDec::from(("Value", value))
                .with_comment(" The value of a case.")
                .with_access(Access::Public),
        )
        .with_function(
            Function::from(
                Signature::from("tag_number")
                    .with_result("std::uint16_t")
                    .with_modifier(Modifier::Const),
            )
            .with_comment(" Gets the tag number of the case.")
            .with_attribute("nodiscard")
            .with_access(Access::Public)
            .with_statement(tag_numbers),
        )
        .with_field(("value_", "Value"));
    for (case, name, _) in cases {
        shape.add_constructor(
            Constructor::from("Shape")
                .with_comment(format!(" Creates the Shape with the `{case}` case."))
                .with_access(Access::Public)
                .with_param((name, case))
                .with_initializer("value_", format!("std::move({name})")),
        );
        shape.add_function(
            Function::from(
                Signature::from(format!("as_{name}"))
                    .with_result(CppType::from(case).to_const().to_pointer())
                    .with_modifier(Modifier::Const)
                    .with_modifier(Modifier::Noexcept),
            )
            .with_comment(format!(
                " Gets the `{case}` case, or null if the shape is another case."
            ))
            .with_attribute("nodiscard")
            .with_access(Access::Public)
            .with_semi(format!("return std::get_if<{case}>(&value_)")),
        );
    }
    let code = Block::default()
        .with_statement(unrecognized)
        .with_empty_line()
        .with_statement(shape);

    let expected = r#"/// A case of a `Shape` that the variant doesn't know.
struct UnrecognizedShape {
    /// The tag number of the case.
    std::uint16_t tag_number;

    /// The encoding of the value of the case.
    std::vector<std::uint8_t> bytes;
};

/// The `Shape` example of `format/binary.md`.
class Shape {
public:
    /// The value of a case.
    using Value = std::variant<UnrecognizedShape, Circle, Square>;

    /// Creates the Shape with the `Circle` case.
    Shape(Circle circle) : value_(std::move(circle)) {}

    /// Creates the Shape with the `Square` case.
    Shape(Square square) : value_(std::move(square)) {}

    /// Gets the tag number of the case.
    [[nodiscard]] std::uint16_t tag_number() const {
        switch (value_.index()) {
            case 1: {
                return 1;
            }
            case 2: {
                return 2;
            }
            default: {
                return std::get<UnrecognizedShape>(value_).tag_number;
            }
        }
    }

    /// Gets the `Circle` case, or null if the shape is another case.
    [[nodiscard]] const Circle* as_circle() const noexcept {
        return std::get_if<Circle>(&value_);
    }

    /// Gets the `Square` case, or null if the shape is another case.
    [[nodiscard]] const Square* as_square() const noexcept {
        return std::get_if<Square>(&value_);
    }

private:
    Value value_;
};
"#;
    assert_eq!(code.to_code(), expected);
}

#[test]
fn view_interface() {
    let fields = [("x", 0), ("y", 4)];
    let mut view = Class::from("PointView")
        .with_comment(" The fields of any form of a `Point`.")
        .with_virtual_destructor(true);
    let mut encode = Function::from(point_encode())
        .with_comment(" Encodes the struct.")
        .with_attribute("nodiscard")
        .with_access(Access::Public)
        .with_semi(format!("{} out", bytes_type()));
    let mut reference = Class::from("PointRef")
        .with_comment(" A `Point` that reads its fields from its encoding.")
        .with_base("PointView")
        .with_constructor(
            Constructor::from("PointRef")
                .with_comment(" Creates the PointRef of the `bytes`, which are a valid encoding.")
                .with_access(Access::Public)
                .with_modifier(Modifier::Explicit)
                .with_modifier(Modifier::Noexcept)
                .with_param(("bytes", span_type()))
                .with_initializer("bytes_", "bytes"),
        )
        .with_field(("bytes_", span_type()));
    for (field, offset) in fields {
        let getter = Signature::from(field)
            .with_result("std::uint32_t")
            .with_modifier(Modifier::Const);
        view.add_signature_dec(
            SignatureDec::from(
                getter
                    .clone()
                    .with_modifier(Modifier::Virtual)
                    .with_modifier(Modifier::PureVirtual),
            )
            .with_comment(format!(" Gets the field: `{field}`."))
            .with_attribute("nodiscard")
            .with_access(Access::Public),
        );
        encode.add_semi(format!(
            "proto_packet::io::write_u32({field}(), std::back_inserter(out))"
        ));
        reference.add_function(
            Function::from(getter.with_modifier(Modifier::Override))
                .with_attribute("nodiscard")
                .with_access(Access::Public)
                .with_semi(format!(
                    "return proto_packet::io::read_u32(bytes_, {offset})"
                )),
        );
    }
    view.add_function(encode.with_semi("return out"));
    let code = Block::default()
        .with_statement(view)
        .with_empty_line()
        .with_statement(reference);

    let expected = r#"/// The fields of any form of a `Point`.
class PointView {
public:
    virtual ~PointView() = default;

    /// Gets the field: `x`.
    [[nodiscard]] virtual std::uint32_t x() const = 0;

    /// Gets the field: `y`.
    [[nodiscard]] virtual std::uint32_t y() const = 0;

    /// Encodes the struct.
    [[nodiscard]] std::vector<std::uint8_t> encode() const {
        std::vector<std::uint8_t> out;
        proto_packet::io::write_u32(x(), std::back_inserter(out));
        proto_packet::io::write_u32(y(), std::back_inserter(out));
        return out;
    }
};

/// A `Point` that reads its fields from its encoding.
class PointRef : public PointView {
public:
    /// Creates the PointRef of the `bytes`, which are a valid encoding.
    explicit PointRef(std::span<const std::uint8_t> bytes) noexcept : bytes_(bytes) {}

    [[nodiscard]] std::uint32_t x() const override {
        return proto_packet::io::read_u32(bytes_, 0);
    }

    [[nodiscard]] std::uint32_t y() const override {
        return proto_packet::io::read_u32(bytes_, 4);
    }

private:
    std::span<const std::uint8_t> bytes_;
};
"#;
    assert_eq!(code.to_code(), expected);
}

#[test]
fn message() {
    let string_type = CppType::from("std::string");
    let name_type = CppType::from("std::optional").with_generic(string_type.clone());
    let emails_type = CppType::from("std::vector").with_generic(string_type.clone());
    let fields = SwitchStatement::from("reader.next_tag_number()")
        .with_switch_case(SwitchCase::from("1").with_semi("result.name_ = reader.read_string()"))
        .with_switch_case(
            SwitchCase::from("2").with_semi("result.emails_.push_back(reader.read_string())"),
        )
        .with_switch_case(SwitchCase::default().with_semi("reader.skip()"));
    let decode = Function::from(
        Signature::from("decode")
            .with_param(("bytes", span_type()))
            .with_result(CppType::from("std::optional").with_generic("Person"))
            .with_modifier(Modifier::Static),
    )
    .with_comment(" Decodes the message from the `bytes`.")
    .with_comment("")
    .with_comment(" Returns nothing if the `bytes` are not a valid encoding.")
    .with_attribute("nodiscard")
    .with_access(Access::Public)
    .with_semi("Person result")
    .with_semi("proto_packet::io::Reader reader(bytes)")
    .with_statement(WhileLoop::from("reader.has_next()").with_statement(fields))
    .with_statement(
        IfStatement::from("!reader.is_valid()")
            .with_success_statements(Block::default().with_semi("return std::nullopt")),
    )
    .with_semi("return result");
    let mut person = Class::from("Person")
        .with_comment(" The `Person` example of `format/binary.md`.")
        .with_function(decode);
    for (field, field_type) in [("name", name_type), ("emails", emails_type)] {
        person.add_function(
            Function::from(
                Signature::from(field)
                    .with_result(field_type.clone().to_const().to_ref())
                    .with_modifier(Modifier::Const)
                    .with_modifier(Modifier::Noexcept),
            )
            .with_comment(format!(" Gets the field: `{field}`."))
            .with_attribute("nodiscard")
            .with_access(Access::Public)
            .with_semi(format!("return {field}_")),
        );
        person.add_function(
            Function::from(
                Signature::from(format!("set_{field}")).with_param((field, field_type.clone())),
            )
            .with_comment(format!(" Sets the field: `{field}`."))
            .with_access(Access::Public)
            .with_semi(format!("{field}_ = std::move({field})")),
        );
        person.add_field((format!("{field}_"), field_type));
    }
    let encode_to = Function::from(
        Signature::from("encode_to")
            .with_param(("out", bytes_type().to_ref()))
            .with_modifier(Modifier::Const),
    )
    .with_comment(" Appends the encoding of the message to the `out` bytes.")
    .with_access(Access::Public)
    .with_statement(IfStatement::from("name_").with_success_statements(
        Block::default().with_semi("proto_packet::io::write_string(1, *name_, out)"),
    ))
    .with_statement(
        ForLoop::from(format!(
            "{} email : emails_",
            string_type.to_const().to_ref()
        ))
        .with_semi("proto_packet::io::write_string(2, email, out)"),
    );
    let person = person.with_function(encode_to);

    let expected = r#"/// The `Person` example of `format/binary.md`.
class Person {
public:
    /// Decodes the message from the `bytes`.
    ///
    /// Returns nothing if the `bytes` are not a valid encoding.
    [[nodiscard]] static std::optional<Person> decode(std::span<const std::uint8_t> bytes) {
        Person result;
        proto_packet::io::Reader reader(bytes);
        while (reader.has_next()) {
            switch (reader.next_tag_number()) {
                case 1: {
                    result.name_ = reader.read_string();
                    break;
                }
                case 2: {
                    result.emails_.push_back(reader.read_string());
                    break;
                }
                default: {
                    reader.skip();
                    break;
                }
            }
        }
        if (!reader.is_valid()) {
            return std::nullopt;
        }
        return result;
    }

    /// Gets the field: `name`.
    [[nodiscard]] const std::optional<std::string>& name() const noexcept {
        return name_;
    }

    /// Sets the field: `name`.
    void set_name(std::optional<std::string> name) {
        name_ = std::move(name);
    }

    /// Gets the field: `emails`.
    [[nodiscard]] const std::vector<std::string>& emails() const noexcept {
        return emails_;
    }

    /// Sets the field: `emails`.
    void set_emails(std::vector<std::string> emails) {
        emails_ = std::move(emails);
    }

    /// Appends the encoding of the message to the `out` bytes.
    void encode_to(std::vector<std::uint8_t>& out) const {
        if (name_) {
            proto_packet::io::write_string(1, *name_, out);
        }
        for (const std::string& email : emails_) {
            proto_packet::io::write_string(2, email, out);
        }
    }

private:
    std::optional<std::string> name_;
    std::vector<std::string> emails_;
};
"#;
    assert_eq!(person.to_code(), expected);
}

#[test]
fn service() {
    /// Gets the statements that route a request to the `call` with the `request` type.
    fn route(call: &str, request: &str) -> Block {
        Block::default()
            .with_statement(VarInit::from((
                ("decoded", CppType::from("auto").to_const()),
                Literal::from(format!("{request}::decode(request)")),
            )))
            .with_statement(
                IfStatement::from("!decoded")
                    .with_success_statements(Block::default().with_semi("return std::nullopt")),
            )
            .with_semi(format!("return service.{call}(*decoded).encode()"))
    }

    let mut greeter = Class::from("Greeter")
        .with_comment(" A service that greets people.")
        .with_virtual_destructor(true);
    for (call, type_name, comment) in [
        ("hello", "Hello", " Greets a person."),
        ("goodbye", "Goodbye", " Says goodbye to a person."),
    ] {
        let request = CppType::from(format!("{type_name}Request"));
        greeter.add_signature_dec(
            SignatureDec::from(
                Signature::from(call)
                    .with_param(("request", request.to_const().to_ref()))
                    .with_result(format!("{type_name}Response"))
                    .with_modifier(Modifier::Virtual)
                    .with_modifier(Modifier::PureVirtual),
            )
            .with_comment(comment)
            .with_access(Access::Public),
        );
    }
    let router = IfStatement::from("call == \"hello\"")
        .with_success_statements(route("hello", "HelloRequest"))
        .with_else_if("call == \"goodbye\"", route("goodbye", "GoodbyeRequest"))
        .with_else_statements(Block::default().with_semi("return std::nullopt"));
    let route_greeter = Function::from(
        Signature::from("route_greeter")
            .with_param(("service", CppType::from("Greeter").to_ref()))
            .with_param(("call", "std::string_view"))
            .with_param(("request", span_type()))
            .with_result(CppType::from("std::optional").with_generic(bytes_type()))
            .with_modifier(Modifier::Inline),
    )
    .with_comment(" Routes the encoded `request` to the `call` of the `service`.")
    .with_comment("")
    .with_comment(
        " Returns the encoded response, or nothing if the `call` or the `request` is invalid.",
    )
    .with_attribute("nodiscard")
    .with_statement(router);
    let code = Block::default()
        .with_statement(greeter)
        .with_empty_line()
        .with_statement(route_greeter);

    let expected = r#"/// A service that greets people.
class Greeter {
public:
    virtual ~Greeter() = default;

    /// Greets a person.
    virtual HelloResponse hello(const HelloRequest& request) = 0;

    /// Says goodbye to a person.
    virtual GoodbyeResponse goodbye(const GoodbyeRequest& request) = 0;
};

/// Routes the encoded `request` to the `call` of the `service`.
///
/// Returns the encoded response, or nothing if the `call` or the `request` is invalid.
[[nodiscard]] inline std::optional<std::vector<std::uint8_t>> route_greeter(Greeter& service, std::string_view call, std::span<const std::uint8_t> request) {
    if (call == "hello") {
        const auto decoded = HelloRequest::decode(request);
        if (!decoded) {
            return std::nullopt;
        }
        return service.hello(*decoded).encode();
    } else if (call == "goodbye") {
        const auto decoded = GoodbyeRequest::decode(request);
        if (!decoded) {
            return std::nullopt;
        }
        return service.goodbye(*decoded).encode();
    } else {
        return std::nullopt;
    }
}
"#;
    assert_eq!(code.to_code(), expected);
}
